import React, { useState } from 'react';
import SlideCard from './components/SlideCard';
import VerticalNav from './components/VerticalNav';
import { useTypewriter } from './utils/typewriter';
import { Shield } from 'lucide-react';
import { motion } from 'framer-motion';

const slides = [
  {
    id: 'slide1',
    title: 'Phishing 101 - Jangan Jadi Korban!',
    subtitle: 'Belajar Mengenali dan Menghindari Serangan Phishing',
    icon: 'shield',
    logo: '/logo-hacktiv8.png',
    animation: 'fade-in-up',
  },
  {
    id: 'slide2',
    title: 'Tentang Pembicara',
    name: 'Kiell Tampubolon',
    role: 'Cybersecurity Engineer, Singapore',
    photo: '/IMG_8642.jpg',
    animation: 'parallax-fade-in',
  },
];

function App() {
  const [current, setCurrent] = useState(0);
  const slide = slides[current];

  // Typewriter effect for Slide 1
  const typedTitle = useTypewriter(slide.id === 'slide1' ? slide.title : '', 40);
  const typedSubtitle = useTypewriter(slide.id === 'slide1' ? slide.subtitle : '', 20);

  // Fullscreen handler
  const handleFullscreen = () => {
    const elem = document.documentElement;
    if (document.fullscreenElement) {
      document.exitFullscreen();
    } else {
      elem.requestFullscreen();
    }
  };

  return (
    <div className="min-h-screen w-full bg-gradient-to-br from-orange-500 via-orange-600 to-red-700 flex items-center justify-center relative overflow-x-hidden">
      {/* Logo Hacktiv8 kanan atas */}
      {slide.logo && (
        <img src={slide.logo} alt="Hacktiv8 Logo" className="fixed top-6 right-8 w-24 h-auto z-40 drop-shadow-lg" />
      )}
      {/* Slide Content */}
      <div className="w-full flex items-center justify-center min-h-screen">
        <SlideCard>
          {/* Slide 1: Judul */}
          {slide.id === 'slide1' && (
            <div className="flex flex-col items-center">
              <motion.div
                animate={{ rotate: [0, 20, -20, 0], scale: [1, 1.2, 1] }}
                transition={{ repeat: Infinity, duration: 2 }}
                className="mb-6"
              >
                <Shield size={64} className="text-orange-600 drop-shadow-lg" />
              </motion.div>
              <h1 className="slide-title text-4xl md:text-5xl font-extrabold mb-4 text-white">
                {typedTitle}
              </h1>
              <h2 className="slide-subtitle text-xl md:text-2xl text-orange-100 font-medium">
                {typedSubtitle}
              </h2>
            </div>
          )}
          {/* Slide 2: Tentang Pembicara */}
          {slide.id === 'slide2' && (
            <div className="flex flex-col items-center">
              <div className="w-32 h-32 rounded-full overflow-hidden shadow-lg mb-4 border-4 border-orange-200">
                <img src={slide.photo} alt="Foto Pembicara" className="object-cover w-full h-full" />
              </div>
              <h2 className="slide-title text-2xl md:text-3xl font-bold text-white mb-2">{slide.name}</h2>
              <div className="slide-subtitle text-orange-100 mb-2">{slide.role}</div>
              <div className="slide-text text-white/90 text-center">Cybersecurity enthusiast, passionate about phishing awareness and digital safety.</div>
            </div>
          )}
        </SlideCard>
      </div>
      {/* Vertical Navigation */}
      <VerticalNav
        current={current}
        total={slides.length}
        onPrev={() => setCurrent((c) => Math.max(0, c - 1))}
        onNext={() => setCurrent((c) => Math.min(slides.length - 1, c + 1))}
        onFullscreen={handleFullscreen}
      />
    </div>
  );
}

export default App;
